class Solution {
    public int minMalwareSpread(int[][] graph,int[] initial){
        int n=graph.length;
        boolean[] bad=new boolean[n];
        for(int x:initial)bad[x]=true;
        int[] parent=new int[n],size=new int[n];
        for(int i=0;i<n;i++){
            parent[i]=i;
            size[i]=1;
        }
        for(int i=0;i<n;i++)if(!bad[i])for(int j=i+1;j<n;j++)if(!bad[j]&&graph[i][j]==1)union(i,j,parent,size);
        List<Set<Integer>> reaches=new ArrayList<>();
        int[] touch=new int[n];
        for(int source:initial){
            Set<Integer> roots=new HashSet<>();
            for(int v=0;v<n;v++)if(!bad[v]&&graph[source][v]==1)roots.add(find(v,parent));
            for(int root:roots)touch[root]++;
            reaches.add(roots);
        }
        int[] order=initial.clone();
        Arrays.sort(order);
        int answer=order[0],best=-1;
        for(int source:order){
            int index=0;
            while(initial[index]!=source)index++;
            int saved=0;
            for(int root:reaches.get(index))if(touch[root]==1)saved+=size[root];
            if(saved>best){
                best=saved;
                answer=source;
            }
        }
        return answer;
    }
    private int find(int x,int[] p){
        return p[x]==x?x:(p[x]=find(p[x],p));
    }
    private void union(int a,int b,int[] p,int[] s){
        a=find(a,p);
        b=find(b,p);
        if(a==b)return;
        if(s[a]<s[b]){
            int t=a;
            a=b;
            b=t;
        }
        p[b]=a;
        s[a]+=s[b];
    }
}

