class Solution {
    fun minMalwareSpread(graph:Array<IntArray>,initial:IntArray):Int{
        val n=graph.size;
        val bad=BooleanArray(n);
        for(x in initial)bad[x]=true;
        val parent=IntArray(n){
            it
        };
        val size=IntArray(n){
            1
        };
        fun find(xInput:Int):Int{
            var x=xInput;
            while(parent[x]!=x){
                parent[x]=parent[parent[x]];
                x=parent[x]
            };
            return x
        };
        fun union(aInput:Int,bInput:Int){
            var a=find(aInput);
            var b=find(bInput);
            if(a==b)return;
            if(size[a]<size[b]){
                val t=a;
                a=b;
                b=t
            };
            parent[b]=a;
            size[a]+=size[b]
        };
        for(i in 0 until n)if(!bad[i])for(j in i+1 until n)if(!bad[j]&&graph[i][j]==1)union(i,j);
        val reaches=Array(initial.size){
            mutableSetOf<Int>()
        };
        val touch=IntArray(n);
        for(index in initial.indices){
            val source=initial[index];
            for(v in 0 until n)if(!bad[v]&&graph[source][v]==1)reaches[index].add(find(v));
            for(root in reaches[index])touch[root]++
        };
        var answer=initial.minOrNull()!!;
        var best=-1;
        for(source in initial.sorted()){
            val index=initial.indexOf(source);
            var saved=0;
            for(root in reaches[index])if(touch[root]==1)saved+=size[root];
            if(saved>best){
                best=saved;
                answer=source
            }
        };
        return answer
    }
}

