class Solution {
    vector<int> parent,size;
    int find(int x){
        return parent[x]==x?x:parent[x]=find(parent[x]);
    }
    void unite(int a,int b){
        a=find(a);
        b=find(b);
        if(a==b)return;
        if(size[a]<size[b])swap(a,b);
        parent[b]=a;
        size[a]+=size[b];
    }
    public:int minMalwareSpread(vector<vector<int>>& graph,vector<int>& initial){
        int n=graph.size();
        vector<bool> bad(n);
        for(int x:initial)bad[x]=true;
        parent.resize(n);
        iota(parent.begin(),parent.end(),0);
        size.assign(n,1);
        for(int i=0;i<n;++i)if(!bad[i])for(int j=i+1;j<n;++j)if(!bad[j]&&graph[i][j])unite(i,j);
        vector<unordered_set<int>> reaches(initial.size());
        vector<int> touch(n);
        for(int index=0;index<(int)initial.size();++index){
            int source=initial[index];
            for(int v=0;v<n;++v)if(!bad[v]&&graph[source][v])reaches[index].insert(find(v));
            for(int root:reaches[index])++touch[root];
        }
        vector<int> order=initial;
        sort(order.begin(),order.end());
        int answer=order[0],best=-1;
        for(int source:order){
            int index=std::find(initial.begin(),initial.end(),source)-initial.begin(),saved=0;
            for(int root:reaches[index])if(touch[root]==1)saved+=size[root];
            if(saved>best){
                best=saved;
                answer=source;
            }
        }
        return answer;
    }
};
